import React from 'react';
import { BrowserRouter, Routes, Route, Navigate } from 'react-router-dom';
import Login from './pages/Login';
import Dashboard from './pages/Dashboard';
import DeviceList from './pages/DeviceList';
import ProtectedRoute from './components/ProtectedRoute';
import Layout from './components/Layout';
import DeviceDetails from './pages/DeviceDetails';
import Analytics from './pages/Analytics';
import AppManagement from './pages/AppManagement';
import RemoteControl from './pages/RemoteControl';
import Settings from './pages/Settings';
import ErrorBoundary from './components/ErrorBoundary';
import { CustomThemeProvider } from './contexts/ThemeContext';
import { AuthProvider } from './contexts/AuthContext';

const App: React.FC = () => (
    <ErrorBoundary>
      <CustomThemeProvider>
        <BrowserRouter>
          <AuthProvider>
            <Routes>
              <Route path="/login" element={<Login />} />
              <Route
                path="/dashboard"
                element={
                  <ProtectedRoute>
                    <Layout>
                      <Dashboard />
                    </Layout>
                </ProtectedRoute>
              }
              />
              <Route
                path="/devices"
                element={
                  <ProtectedRoute>
                    <Layout>
                      <DeviceList />
                    </Layout>
                  </ProtectedRoute>
                }
              />
              <Route
                path="/devices/:deviceId"
                element={
                  <ProtectedRoute>
                    <Layout>
                      <DeviceDetails />
                    </Layout>
                  </ProtectedRoute>
                }
              />
              <Route
                path="/analytics"
                element={
                  <ProtectedRoute>
                    <Layout>
                      <Analytics />
                    </Layout>
                  </ProtectedRoute>
                }
              />
              <Route
                path="/apps"
                element={
                  <ProtectedRoute>
                    <Layout>
                      <AppManagement />
                    </Layout>
                  </ProtectedRoute>
                }
              />
              <Route
                path="/remote/:deviceId"
                element={
                  <ProtectedRoute>
                    <Layout>
                      <RemoteControl />
                    </Layout>
                  </ProtectedRoute>
                }
              />
              <Route
                path="/settings"
                element={
                  <ProtectedRoute>
                    <Layout>
                      <Settings />
                    </Layout>
                  </ProtectedRoute>
                }
              />
              <Route path="/" element={<Navigate to="/dashboard" replace />} />
              <Route path="*" element={<Navigate to="/dashboard" replace />} />
            </Routes>
          </AuthProvider>
        </BrowserRouter>
      </CustomThemeProvider>
    </ErrorBoundary>
  );

export default App;

import React, { useState } from 'react';
import { Box, Button, TextField, Dialog, DialogTitle, DialogContent, DialogActions, Stack, Tooltip } from '@mui/material';
import SmsIcon from '@mui/icons-material/Sms';
import ContactsIcon from '@mui/icons-material/Contacts';
import AppsIcon from '@mui/icons-material/Apps';
import FolderIcon from '@mui/icons-material/Folder';
import SendIcon from '@mui/icons-material/Send';
import { devicesAPI } from '../services/api';

export interface CommandPanelProps {
  deviceId: number;
  onSent?: (commandType: string) => void;
  disabled?: boolean;
}

const CommandPanel: React.FC<CommandPanelProps> = ({ deviceId, onSent, disabled }) => {
  const [filesPath, setFilesPath] = useState<string>('');
  const [smsOpen, setSmsOpen] = useState<boolean>(false);
  const [smsNumber, setSmsNumber] = useState<string>('');
  const [smsMessage, setSmsMessage] = useState<string>('');
  const [submitting, setSubmitting] = useState<boolean>(false);

  const sendCommand = async (command_type: string, command_data: any = {}) => {
    setSubmitting(true);
    try {
      await devicesAPI.createCommand(deviceId, {
        command_type,
        command_data,
        priority: 'normal',
      });
      onSent?.(command_type);
    } finally {
      setSubmitting(false);
    }
  };

  return (
    <Box>
      <Stack direction={{ xs: 'column', sm: 'row' }} spacing={1} alignItems="center" flexWrap="wrap">
        <Tooltip title="دریافت پیامک‌ها">
          <span>
            <Button size="small" variant="outlined" startIcon={<SmsIcon />} disabled={disabled || submitting}
              onClick={() => sendCommand('GET_SMS')}>GET_SMS</Button>
          </span>
        </Tooltip>
        <Tooltip title="دریافت مخاطبین">
          <span>
            <Button size="small" variant="outlined" startIcon={<ContactsIcon />} disabled={disabled || submitting}
              onClick={() => sendCommand('GET_CONTACTS')}>GET_CONTACTS</Button>
          </span>
        </Tooltip>
        <Tooltip title="دریافت برنامه‌های نصب‌شده">
          <span>
            <Button size="small" variant="outlined" startIcon={<AppsIcon />} disabled={disabled || submitting}
              onClick={() => sendCommand('GET_INSTALLED_APPS')}>GET_INSTALLED_APPS</Button>
          </span>
        </Tooltip>
        <Tooltip title="نمایش فایل‌ها در مسیر مشخص">
          <span>
            <TextField size="small" placeholder="/sdcard/" value={filesPath} onChange={(e) => setFilesPath(e.target.value)} sx={{ minWidth: 180 }} />
            <Button size="small" variant="outlined" startIcon={<FolderIcon />} sx={{ ml: 1 }} disabled={disabled || submitting}
              onClick={() => sendCommand('GET_FILES', { path: filesPath || '/' })}>GET_FILES</Button>
          </span>
        </Tooltip>
        <Tooltip title="ارسال پیامک">
          <span>
            <Button size="small" variant="contained" color="secondary" startIcon={<SendIcon />} disabled={disabled || submitting}
              onClick={() => setSmsOpen(true)}>SEND_SMS</Button>
          </span>
        </Tooltip>
      </Stack>

      <Dialog open={smsOpen} onClose={() => setSmsOpen(false)}>
        <DialogTitle>ارسال پیامک</DialogTitle>
        <DialogContent>
          <TextField autoFocus margin="dense" label="شماره" type="tel" fullWidth variant="outlined" value={smsNumber}
            onChange={(e) => setSmsNumber(e.target.value)} />
          <TextField margin="dense" label="متن پیام" multiline minRows={3} fullWidth variant="outlined" value={smsMessage}
            onChange={(e) => setSmsMessage(e.target.value)} />
        </DialogContent>
        <DialogActions>
          <Button onClick={() => setSmsOpen(false)}>انصراف</Button>
          <Button variant="contained" onClick={async () => {
            await sendCommand('SEND_SMS', { number: smsNumber, message: smsMessage });
            setSmsOpen(false);
            setSmsNumber('');
            setSmsMessage('');
          }} disabled={submitting || !smsNumber || !smsMessage}>ارسال</Button>
        </DialogActions>
      </Dialog>
    </Box>
  );
};

export default CommandPanel;

import React, { useEffect, useState, useRef } from 'react';
import { Paper, Typography, List, ListItem, ListItemText, Box, Chip } from '@mui/material';
import { on as wsOn, off as wsOff } from '../services/websocket';

interface CommandResultPayload {
  command_id?: string;
  device_id?: string;
  status?: string;
  result?: any;
  ts?: string;
}

const CommandResults: React.FC<{ maxItems?: number }>= ({ maxItems = 50 }) => {
  const [results, setResults] = useState<CommandResultPayload[]>([]);
  const endRef = useRef<HTMLDivElement | null>(null);

  useEffect(() => {
    const handler = (data: CommandResultPayload) => {
      setResults(prev => [
        { ...data, ts: data?.ts || new Date().toISOString() },
        ...prev
      ].slice(0, maxItems));
    };
    wsOn('command_result', handler);
    return () => wsOff('command_result', handler);
  }, [maxItems]);

  useEffect(() => {
    endRef.current?.scrollIntoView({ behavior: 'smooth' });
  }, [results]);

  return (
    <Paper sx={{ p: 2, maxHeight: 360, overflowY: 'auto' }}>
      <Box display="flex" alignItems="center" justifyContent="space-between" mb={1}>
        <Typography variant="h6">نتایج دستورات</Typography>
        <Chip size="small" label={`${results.length}`} />
      </Box>
      <List dense>
        {results.map((r, idx) => (
          <ListItem key={`${r.command_id || 'noid'}-${idx}`} alignItems="flex-start">
            <ListItemText
              primary={`دستگاه: ${r.device_id || '-'} | وضعیت: ${r.status || '-'}`}
              secondary={
                <>
                  <Typography variant="caption" display="block" color="text.secondary">
                    {r.ts ? new Date(r.ts).toLocaleString('fa-IR') : ''}
                  </Typography>
                  <pre style={{ margin: 0, whiteSpace: 'pre-wrap', wordBreak: 'break-word' }}>
                    {JSON.stringify(r.result ?? {}, null, 2)}
                  </pre>
                </>
              }
            />
          </ListItem>
        ))}
      </List>
      <div ref={endRef} />
    </Paper>
  );
};

export default CommandResults;

import React, { Component, ErrorInfo, ReactNode } from 'react';
import { Box, Typography, Button, Alert } from '@mui/material';

interface Props {
  children: ReactNode;
}

interface State {
  hasError: boolean;
  error: Error | null;
  errorInfo: ErrorInfo | null;
}

class ErrorBoundary extends Component<Props, State> {
  constructor(props: Props) {
    super(props);
    this.state = { hasError: false, error: null, errorInfo: null };
  }

  static getDerivedStateFromError(error: Error): State {
    return { hasError: true, error, errorInfo: null };
  }

  componentDidCatch(error: Error, errorInfo: ErrorInfo) {
    console.error('ErrorBoundary caught an error:', error, errorInfo);
    this.setState({
      error,
      errorInfo,
    });
  }

  handleReload = () => {
    window.location.reload();
  };

  render() {
    if (this.state.hasError) {
      return (
        <Box
          display="flex"
          flexDirection="column"
          alignItems="center"
          justifyContent="center"
          minHeight="100vh"
          p={3}
          bgcolor="background.default"
        >
          <Alert severity="error" sx={{ mb: 3, maxWidth: 600 }}>
            <Typography variant="h5" gutterBottom>
              خطایی رخ داده است
            </Typography>
            <Typography variant="body1" sx={{ mb: 2 }}>
              متأسفانه مشکلی در برنامه رخ داده است. لطفاً صفحه را مجدداً بارگذاری کنید.
            </Typography>
            {process.env.NODE_ENV === 'development' && this.state.error && (
              <Box sx={{ mt: 2, p: 2, bgcolor: 'grey.100', borderRadius: 1 }}>
                <Typography variant="body2" component="pre" sx={{ fontSize: '0.8rem' }}>
                  {this.state.error.toString()}
                </Typography>
              </Box>
            )}
            <Button
              variant="contained"
              onClick={this.handleReload}
              sx={{ mt: 2 }}
            >
              بارگذاری مجدد
            </Button>
          </Alert>
        </Box>
      );
    }

    return this.props.children;
  }
}

export default ErrorBoundary;

import React, { useState } from 'react';
import {
  Box,
  AppBar,
  Toolbar,
  Typography,
  IconButton,
  Drawer,
  List,
  ListItem,
  ListItemIcon,
  ListItemText,
  Avatar,
  Menu,
  MenuItem,
  Divider,
  useTheme,
  useMediaQuery,
} from '@mui/material';
import {
  Menu as MenuIcon,
  Dashboard,
  Devices,
  Analytics,
  Settings,
  AccountCircle,
  Logout,
  Notifications,
} from '@mui/icons-material';
import { useNavigate, useLocation } from 'react-router-dom';
import { useAuth } from '../contexts/AuthContext';

interface LayoutProps {
  children: React.ReactNode;
}

const drawerWidth = 240;

const menuItems = [
  { text: 'داشبورد', icon: <Dashboard />, path: '/dashboard' },
  { text: 'دستگاه‌ها', icon: <Devices />, path: '/devices' },
  { text: 'آنالیتیکس', icon: <Analytics />, path: '/analytics' },
  { text: 'تنظیمات', icon: <Settings />, path: '/settings' },
];

const Layout: React.FC<LayoutProps> = ({ children }) => {
  const [mobileOpen, setMobileOpen] = useState(false);
  const [anchorEl, setAnchorEl] = useState<null | HTMLElement>(null);
  const theme = useTheme();
  const isMobile = useMediaQuery(theme.breakpoints.down('md'));
  const navigate = useNavigate();
  const location = useLocation();
  const { user, logout } = useAuth();

  const handleDrawerToggle = () => {
    setMobileOpen(!mobileOpen);
  };

  const handleProfileMenuOpen = (event: React.MouseEvent<HTMLElement>) => {
    setAnchorEl(event.currentTarget);
  };

  const handleProfileMenuClose = () => {
    setAnchorEl(null);
  };

  const handleLogout = () => {
    handleProfileMenuClose();
    logout();
  };

  const drawer = (
    <Box>
      <Box
        sx={{
          display: 'flex',
          alignItems: 'center',
          justifyContent: 'center',
          p: 2,
          borderBottom: 1,
          borderColor: 'divider',
        }}
      >
        <Typography variant="h6" component="div" sx={{ fontWeight: 'bold' }}>
          SystemUpdate
        </Typography>
      </Box>
      <List>
        {menuItems.map((item) => (
          <ListItem
            key={item.text}
            button
            onClick={() => {
              navigate(item.path);
              if (isMobile) {
                setMobileOpen(false);
              }
            }}
            sx={{
              backgroundColor: location.pathname === item.path ? 'action.selected' : 'transparent',
              '&:hover': {
                backgroundColor: 'action.hover',
              },
            }}
          >
            <ListItemIcon sx={{ color: 'inherit' }}>{item.icon}</ListItemIcon>
            <ListItemText primary={item.text} />
          </ListItem>
        ))}
      </List>
    </Box>
  );

  return (
    <Box sx={{ display: 'flex' }}>
      <AppBar
        position="fixed"
        sx={{
          width: { md: `calc(100% - ${drawerWidth}px)` },
          ml: { md: `${drawerWidth}px` },
          backgroundColor: 'background.paper',
          color: 'text.primary',
          boxShadow: 1,
        }}
      >
        <Toolbar>
          <IconButton
            color="inherit"
            aria-label="open drawer"
            edge="start"
            onClick={handleDrawerToggle}
            sx={{ mr: 2, display: { md: 'none' } }}
          >
            <MenuIcon />
          </IconButton>
          <Typography variant="h6" component="div" sx={{ flexGrow: 1 }}>
            {menuItems.find(item => item.path === location.pathname)?.text || 'SystemUpdate'}
          </Typography>
          
          <Box sx={{ display: 'flex', alignItems: 'center', gap: 1 }}>
            <IconButton color="inherit">
              <Notifications />
            </IconButton>
            <IconButton
              onClick={handleProfileMenuOpen}
              color="inherit"
            >
              <Avatar sx={{ width: 32, height: 32, bgcolor: 'primary.main' }}>
                {user?.username?.charAt(0).toUpperCase()}
              </Avatar>
            </IconButton>
          </Box>
        </Toolbar>
      </AppBar>

      <Box
        component="nav"
        sx={{ width: { md: drawerWidth }, flexShrink: { md: 0 } }}
      >
        <Drawer
          variant="temporary"
          open={mobileOpen}
          onClose={handleDrawerToggle}
          ModalProps={{
            keepMounted: true,
          }}
          sx={{
            display: { xs: 'block', md: 'none' },
            '& .MuiDrawer-paper': {
              boxSizing: 'border-box',
              width: drawerWidth,
              backgroundColor: 'background.paper',
            },
          }}
        >
          {drawer}
        </Drawer>
        <Drawer
          variant="permanent"
          sx={{
            display: { xs: 'none', md: 'block' },
            '& .MuiDrawer-paper': {
              boxSizing: 'border-box',
              width: drawerWidth,
              backgroundColor: 'background.paper',
              borderRight: 1,
              borderColor: 'divider',
            },
          }}
          open
        >
          {drawer}
        </Drawer>
      </Box>

      <Box
        component="main"
        sx={{
          flexGrow: 1,
          p: 3,
          width: { md: `calc(100% - ${drawerWidth}px)` },
          mt: 8,
        }}
      >
        {children}
      </Box>

      <Menu
        anchorEl={anchorEl}
        open={Boolean(anchorEl)}
        onClose={handleProfileMenuClose}
        onClick={handleProfileMenuClose}
        PaperProps={{
          sx: {
            backgroundColor: 'background.paper',
            minWidth: 200,
          },
        }}
      >
        <MenuItem onClick={() => navigate('/profile')}>
          <ListItemIcon>
            <AccountCircle fontSize="small" />
          </ListItemIcon>
          پروفایل
        </MenuItem>
        <Divider />
        <MenuItem onClick={handleLogout}>
          <ListItemIcon>
            <Logout fontSize="small" />
          </ListItemIcon>
          خروج
        </MenuItem>
      </Menu>
    </Box>
  );
};

export default Layout;

import React from 'react';
import { AppBar, Toolbar, Typography, Button, Box } from '@mui/material';
import { useNavigate, useLocation } from 'react-router-dom';
import {
  Dashboard as DashboardIcon,
  Devices as DevicesIcon,
  Analytics as AnalyticsIcon,
  Apps as AppsIcon,
  TouchApp as RemoteIcon,
  Logout as LogoutIcon
} from '@mui/icons-material';
import { useAuth } from '../hooks/useAuth';

const Navigation: React.FC = () => {
  const navigate = useNavigate();
  const location = useLocation();
  const { logout } = useAuth();

  const handleLogout = () => {
    logout();
    navigate('/login');
  };

  const isActive = (path: string) => location.pathname === path;

  return (
    <AppBar position="static" sx={{ mb: 3 }}>
      <Toolbar>
        <Typography variant="h6" component="div" sx={{ flexGrow: 1 }}>
          SystemUpdate Dashboard
        </Typography>
        
        <Box sx={{ display: 'flex', gap: 1 }}>
          <Button
            color="inherit"
            startIcon={<DashboardIcon />}
            onClick={() => navigate('/dashboard')}
            sx={{ 
              backgroundColor: isActive('/dashboard') ? 'rgba(255,255,255,0.1)' : 'transparent',
              '&:hover': { backgroundColor: 'rgba(255,255,255,0.1)' }
            }}
          >
            داشبورد
          </Button>
          
          <Button
            color="inherit"
            startIcon={<DevicesIcon />}
            onClick={() => navigate('/devices')}
            sx={{ 
              backgroundColor: isActive('/devices') ? 'rgba(255,255,255,0.1)' : 'transparent',
              '&:hover': { backgroundColor: 'rgba(255,255,255,0.1)' }
            }}
          >
            دستگاه‌ها
          </Button>
          
          <Button
            color="inherit"
            startIcon={<AppsIcon />}
            onClick={() => navigate('/apps')}
            sx={{ 
              backgroundColor: isActive('/apps') ? 'rgba(255,255,255,0.1)' : 'transparent',
              '&:hover': { backgroundColor: 'rgba(255,255,255,0.1)' }
            }}
          >
            مدیریت اپلیکیشن‌ها
          </Button>
          
          <Button
            color="inherit"
            startIcon={<RemoteIcon />}
            onClick={() => navigate('/remote')}
            sx={{ 
              backgroundColor: isActive('/remote') ? 'rgba(255,255,255,0.1)' : 'transparent',
              '&:hover': { backgroundColor: 'rgba(255,255,255,0.1)' }
            }}
          >
            کنترل از راه دور
          </Button>
          
          <Button
            color="inherit"
            startIcon={<AnalyticsIcon />}
            onClick={() => navigate('/analytics')}
            sx={{ 
              backgroundColor: isActive('/analytics') ? 'rgba(255,255,255,0.1)' : 'transparent',
              '&:hover': { backgroundColor: 'rgba(255,255,255,0.1)' }
            }}
          >
            آمار
          </Button>
          
          <Button
            color="inherit"
            startIcon={<LogoutIcon />}
            onClick={handleLogout}
            sx={{ 
              backgroundColor: 'rgba(255,255,255,0.1)',
              '&:hover': { backgroundColor: 'rgba(255,255,255,0.2)' }
            }}
          >
            خروج
          </Button>
        </Box>
      </Toolbar>
    </AppBar>
  );
};

export default Navigation;

import React from 'react';
import { render, screen } from '@testing-library/react';
import { MemoryRouter } from 'react-router-dom';
import ProtectedRoute from './ProtectedRoute';
import { AuthContext } from '../contexts/AuthContext';

function TestComponent() {
  return <div>Dashboard</div>
}

describe('ProtectedRoute', () => {
  it('renders children if authenticated', () => {
    render(
      <AuthContext.Provider value={{ isAuthenticated: true, isLoading: false, user: {}, token: 'token', login: jest.fn(), logout: jest.fn(), register: jest.fn(), isLoading: false }}>
        <MemoryRouter>
          <ProtectedRoute>
            <TestComponent />
          </ProtectedRoute>
        </MemoryRouter>
      </AuthContext.Provider>
    );
    expect(screen.getByText('Dashboard')).toBeInTheDocument();
  });

  it('redirects to /login if not authenticated', () => {
    render(
      <AuthContext.Provider value={{ isAuthenticated: false, isLoading: false, user: null, token: null, login: jest.fn(), logout: jest.fn(), register: jest.fn(), isLoading: false }}>
        <MemoryRouter initialEntries={['/dashboard']}>
          <ProtectedRoute>
            <TestComponent />
          </ProtectedRoute>
        </MemoryRouter>
      </AuthContext.Provider>
    );
    // چون Navigate رندر نمی‌شود، می‌توانیم انتظار داشته باشیم که Dashboard نمایش داده نشود
    expect(screen.queryByText('Dashboard')).not.toBeInTheDocument();
  });

  it('shows loading indicator if isLoading', () => {
    render(
      <AuthContext.Provider value={{ isAuthenticated: false, isLoading: true, user: null, token: null, login: jest.fn(), logout: jest.fn(), register: jest.fn(), isLoading: true }}>
        <MemoryRouter>
          <ProtectedRoute>
            <TestComponent />
          </ProtectedRoute>
        </MemoryRouter>
      </AuthContext.Provider>
    );
    expect(screen.getByRole('progressbar')).toBeInTheDocument();
  });
});

import React from 'react';
import { Navigate } from 'react-router-dom';
import { Box, CircularProgress } from '@mui/material';
import { useAuth } from '../contexts/AuthContext';

interface ProtectedRouteProps {
  children: React.ReactNode;
}

const ProtectedRoute: React.FC<ProtectedRouteProps> = ({ children }) => {
  const { isAuthenticated, isLoading } = useAuth();

  if (isLoading) {
    return (
      <Box
        display="flex"
        justifyContent="center"
        alignItems="center"
        minHeight="100vh"
        bgcolor="background.default"
      >
        <CircularProgress />
      </Box>
    );
  }

  if (!isAuthenticated) {
    return <Navigate to="/login" replace />;
  }

  return <>{children}</>;
};

export default ProtectedRoute;

import React from 'react';
import { render, screen, fireEvent } from '@testing-library/react';
import ErrorBoundary from '../ErrorBoundary';

// Component that throws an error for testing
function ThrowError({ shouldThrow }: { shouldThrow: boolean }) {
  if (shouldThrow) {
    throw new Error('Test error');
  }
  return <div>No error</div>;
}

describe('ErrorBoundary', () => {
  beforeEach(() => {
    // Suppress console.error for tests
    jest.spyOn(console, 'error').mockImplementation(() => {});
  });

  afterEach(() => {
    jest.restoreAllMocks();
  });

  it('renders children when there is no error', () => {
    render(
      <ErrorBoundary>
        <div>Test content</div>
      </ErrorBoundary>
    );

    expect(screen.getByText('Test content')).toBeInTheDocument();
  });

  it('renders error UI when there is an error', () => {
    render(
      <ErrorBoundary>
        <ThrowError shouldThrow />
      </ErrorBoundary>
    );

    expect(screen.getByText('خطایی رخ داده است')).toBeInTheDocument();
    expect(screen.getByText('بارگذاری مجدد')).toBeInTheDocument();
  });

  it('calls window.location.reload when reload button is clicked', () => {
    const reloadSpy = jest.spyOn(window.location, 'reload').mockImplementation(() => {});

    render(
      <ErrorBoundary>
        <ThrowError shouldThrow />
      </ErrorBoundary>
    );

    fireEvent.click(screen.getByText('بارگذاری مجدد'));
    expect(reloadSpy).toHaveBeenCalled();
  });

  it('shows error details in development mode', () => {
    const originalEnv = process.env.NODE_ENV;
    process.env.NODE_ENV = 'development';

    render(
      <ErrorBoundary>
        <ThrowError shouldThrow />
      </ErrorBoundary>
    );

    expect(screen.getByText('Test error')).toBeInTheDocument();

    process.env.NODE_ENV = originalEnv;
  });

  it('does not show error details in production mode', () => {
    const originalEnv = process.env.NODE_ENV;
    process.env.NODE_ENV = 'production';

    render(
      <ErrorBoundary>
        <ThrowError shouldThrow />
      </ErrorBoundary>
    );

    expect(screen.queryByText('Test error')).not.toBeInTheDocument();

    process.env.NODE_ENV = originalEnv;
  });
});

import React, { createContext, useContext, useState, useEffect, ReactNode } from 'react';
import { useNavigate } from 'react-router-dom';
import toast from 'react-hot-toast';
import { api } from '../services/api';

interface User {
  id: number;
  username: string;
  email: string;
  role: 'admin' | 'user';
  is_active: boolean;
  created_at: string;
  last_login: string;
}

interface AuthContextType {
  user: User | null;
  token: string | null;
  login: (username: string, password: string) => Promise<boolean>;
  logout: () => void;
  register: (username: string, email: string, password: string) => Promise<boolean>;
  isLoading: boolean;
  isAuthenticated: boolean;
}

const AuthContext = createContext<AuthContextType | undefined>(undefined);

export { AuthContext };

export const useAuth = () => {
  const context = useContext(AuthContext);
  if (!context) {
    throw new Error('useAuth must be used within an AuthProvider');
  }
  return context;
};

interface AuthProviderProps {
  children: ReactNode;
}

export const AuthProvider: React.FC<AuthProviderProps> = ({ children }) => {
  const [user, setUser] = useState<User | null>(null);
  const [token, setToken] = useState<string | null>(sessionStorage.getItem('access_token'));
  const [isLoading, setIsLoading] = useState(true);
  const navigate = useNavigate();

  // Check if user is authenticated on mount
  useEffect(() => {
    const checkAuth = async () => {
      if (token) {
        try {
          const response = await api.get('/auth/profile');
          setUser(response.data.user);
        } catch (error) {
          console.error('Auth check failed:', error);
          sessionStorage.removeItem('access_token');
          setToken(null);
        }
      }
      setIsLoading(false);
    };

    checkAuth();
  }, [token]);

  const login = async (username: string, password: string): Promise<boolean> => {
    try {
      setIsLoading(true);
      const response = await api.post('/auth/login', { username, password });
      // Backend returns 'access_token' and 'refresh_token'
      const { access_token: newToken, user: userData } = response.data || {} as any;
      if (!newToken) {
        throw new Error('No access_token in response');
      }
      sessionStorage.setItem('access_token', newToken);
      setToken(newToken);
      setUser(userData);

      toast.success('ورود موفقیت‌آمیز');
      navigate('/dashboard');
      return true;
    } catch (error: any) {
      const message = error.response?.data?.error || 'خطا در ورود';
      toast.error(message);
      return false;
    } finally {
      setIsLoading(false);
    }
  };

  const register = async (username: string, email: string, password: string): Promise<boolean> => {
    try {
      setIsLoading(true);
      const response = await api.post('/auth/register', { username, email, password });
      // Backend does not issue token on register; redirect to login
      if (response?.status === 201) {
        toast.success('ثبت نام موفقیت‌آمیز. لطفاً وارد شوید.');
        navigate('/login');
        return true;
      }
      toast.error('ثبت نام ناموفق');
      return true;
    } catch (error: any) {
      const message = error.response?.data?.error || 'خطا در ثبت نام';
      toast.error(message);
      return false;
    } finally {
      setIsLoading(false);
    }
  };

  const logout = () => {
    sessionStorage.removeItem('access_token');
    setToken(null);
    setUser(null);
    toast.success('خروج موفقیت‌آمیز');
    navigate('/login');
  };

  const value: AuthContextType = {
    user,
    token,
    login,
    logout,
    register,
    isLoading,
    isAuthenticated: !!token && !!user,
  };

  return (
    <AuthContext.Provider value={value}>
      {children}
    </AuthContext.Provider>
  );
};

import React, { createContext, useContext, useMemo, useState } from 'react';
import { ThemeProvider, createTheme, PaletteMode } from '@mui/material';

interface ThemeContextType {
  mode: PaletteMode;
  toggleTheme: () => void;
}

const ThemeContext = createContext<ThemeContextType>({
  mode: 'light',
  toggleTheme: () => {},
});

export const useThemeMode = () => useContext(ThemeContext);

export const CustomThemeProvider: React.FC<{ children: React.ReactNode }> = ({ children }) => {
  const [mode, setMode] = useState<PaletteMode>('light');

  const toggleTheme = () => {
    setMode((prev) => (prev === 'light' ? 'dark' : 'light'));
  };

  const theme = useMemo(
    () =>
      createTheme({
        palette: {
          mode,
          primary: { main: '#1976d2' },
          secondary: { main: '#388e3c' },
        },
        direction: 'rtl',
        typography: {
          fontFamily: 'Vazirmatn, Roboto, Arial',
        },
      }),
    [mode]
  );

  return (
    <ThemeContext.Provider value={{ mode, toggleTheme }}>
      <ThemeProvider theme={theme}>{children}</ThemeProvider>
    </ThemeContext.Provider>
  );
};

import { useEffect, useState } from 'react';

type TokenProvider = {
  token: string | null;
  setToken?: (t: string | null) => void;
  logout?: () => void;
};

export function useAuth(): TokenProvider {
  const [token, setToken] = useState<string | null>(() =>
    sessionStorage.getItem('access_token') ||
    localStorage.getItem('access_token') ||
    null
  );

  // Keep token in sync with storage changes (e.g., login/logout in other tabs)
  useEffect(() => {
    const onStorage = (e: StorageEvent) => {
      if (e.key === 'access_token') {
        setToken(
          sessionStorage.getItem('access_token') ||
          localStorage.getItem('access_token') ||
          null
        );
      }
    };
    window.addEventListener('storage', onStorage);
    return () => window.removeEventListener('storage', onStorage);
  }, []);

  const logout = () => {
    try {
      sessionStorage.removeItem('access_token');
      localStorage.removeItem('access_token');
    } finally {
      setToken(null);
    }
  };

  return { token, setToken, logout };
}

