const AppManagement: React.FC = () => {
  const { token } = useAuth();
  const [apps, setApps] = useState<AppInfo[]>([]);
  const [filteredApps, setFilteredApps] = useState<AppInfo[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState('');
  const [searchTerm, setSearchTerm] = useState('');
  const [selectedTab, setSelectedTab] = useState(0);
  const [selectedApp, setSelectedApp] = useState<AppInfo | null>(null);
  const [snackbarOpen, setSnackbarOpen] = useState(false);
  const [snackbarMsg, setSnackbarMsg] = useState('');
  const [snackbarSeverity, setSnackbarSeverity] = useState<AlertColor>('success');

  // Dialog states
  const [installDialogOpen, setInstallDialogOpen] = useState(false);
  const [apkPath, setApkPath] = useState('');
  const [uiControlDialogOpen, setUiControlDialogOpen] = useState(false);
  const [uiControlData, setUiControlData] = useState<UIControlData>({});
  const [screenshotDialogOpen, setScreenshotDialogOpen] = useState(false);
  const [screenshotData, setScreenshotData] = useState<string>('');

  useEffect(() => {
    fetchApps();
  }, []);

  useEffect(() => {
    filterApps();
  }, [apps, searchTerm]);

  const fetchApps = async () => {
    setLoading(true);
    setError('');
    try {
      if (!token) throw new Error('No access token');

      const response = await axios.post(`${API_URL}/websocket/command`, {
        command: 'app_list',
        payload: {}
      }, {
        headers: { Authorization: `Bearer ${token}` }
      });

      if (response.data.success) {
        const appList = response.data.apps?.installed || [];
        setApps(appList);
        setSnackbarMsg('لیست اپلیکیشن‌ها با موفقیت بارگذاری شد.');
        setSnackbarSeverity('success');
        setSnackbarOpen(true);
      } else {
        throw new Error('خطا در دریافت لیست اپلیکیشن‌ها');
      }
    } catch (err: any) {
      setError(err.response?.data?.error || err.message || 'خطا در دریافت لیست اپلیکیشن‌ها');
      setSnackbarMsg('خطا در دریافت لیست اپلیکیشن‌ها.');
      setSnackbarSeverity('error');
      setSnackbarOpen(true);
    } finally {
      setLoading(false);
    }
  };

  const filterApps = () => {
    if (!searchTerm.trim()) {
      setFilteredApps(apps);
      return;
    }

    const filtered = apps.filter(app =>
      app.app_name.toLowerCase().includes(searchTerm.toLowerCase()) ||
      app.package_name.toLowerCase().includes(searchTerm.toLowerCase())
    );
    setFilteredApps(filtered);
  };

  const handleAppAction = async (action: string, packageName: string) => {
    try {
      if (!token) throw new Error('No access token');

      const response = await axios.post(`${API_URL}/websocket/command`, {
        command: `app_${action}`,
        payload: { package_name: packageName }
      }, {
        headers: { Authorization: `Bearer ${token}` }
      });

      if (response.data.success) {
        setSnackbarMsg(`عملیات ${action} روی اپلیکیشن با موفقیت انجام شد.`);
        setSnackbarSeverity('success');
        setSnackbarOpen(true);
        fetchApps(); // بروزرسانی لیست
      } else {
        throw new Error(`خطا در انجام عملیات ${action}`);
      }
    } catch (err: any) {
      setSnackbarMsg(`خطا در انجام عملیات ${action}: ${err.message}`);
      setSnackbarSeverity('error');
      setSnackbarOpen(true);
    }
  };

  const handleInstallApp = async () => {
    if (!apkPath.trim()) {
      setSnackbarMsg('لطفاً مسیر فایل APK را وارد کنید.');
      setSnackbarSeverity('warning');
      setSnackbarOpen(true);
      return;
    }

    try {
      if (!token) throw new Error('No access token');

      const response = await axios.post(`${API_URL}/websocket/command`, {
        command: 'app_install',
        payload: { apk_path: apkPath }
      }, {
        headers: { Authorization: `Bearer ${token}` }
      });

      if (response.data.success) {
        setSnackbarMsg('اپلیکیشن با موفقیت نصب شد.');
        setSnackbarSeverity('success');
        setSnackbarOpen(true);
        setInstallDialogOpen(false);
        setApkPath('');
        fetchApps();
      } else {
        throw new Error('خطا در نصب اپلیکیشن');
      }
    } catch (err: any) {
      setSnackbarMsg(`خطا در نصب اپلیکیشن: ${err.message}`);
      setSnackbarSeverity('error');
      setSnackbarOpen(true);
    }
  };

  const handleUIControl = async () => {
    try {
      if (!token) throw new Error('No access token');

      const response = await axios.post(`${API_URL}/websocket/command`, {
        command: 'ui_control',
        payload: uiControlData
      }, {
        headers: { Authorization: `Bearer ${token}` }
      });

      if (response.data.success) {
        setSnackbarMsg('عملیات UI با موفقیت انجام شد.');
        setSnackbarSeverity('success');
        setSnackbarOpen(true);
        setUiControlDialogOpen(false);
        setUiControlData({});
      } else {
        throw new Error('خطا در انجام عملیات UI');
      }
    } catch (err: any) {
      setSnackbarMsg(`خطا در انجام عملیات UI: ${err.message}`);
      setSnackbarSeverity('error');
      setSnackbarOpen(true);
    }
  };

  const handleScreenshot = async () => {
    try {
      if (!token) throw new Error('No access token');

      const response = await axios.post(`${API_URL}/websocket/command`, {
        command: 'screenshot',
        payload: {}
      }, {
        headers: { Authorization: `Bearer ${token}` }
      });

      if (response.data.success && response.data.image_data) {
        setScreenshotData(`data:image/jpeg;base64,${response.data.image_data}`);
        setScreenshotDialogOpen(true);
        setSnackbarMsg('اسکرین‌شات با موفقیت گرفته شد.');
        setSnackbarSeverity('success');
        setSnackbarOpen(true);
      } else {
        throw new Error('خطا در گرفتن اسکرین‌شات');
      }
    } catch (err: any) {
      setSnackbarMsg(`خطا در گرفتن اسکرین‌شات: ${err.message}`);
      setSnackbarSeverity('error');
      setSnackbarOpen(true);
    }
  };

  const handleSnackbarClose = (_event?: React.SyntheticEvent | Event, reason?: string) => {
    if (reason === 'clickaway') return;
    setSnackbarOpen(false);
  };

  const getTabApps = () => filteredApps.filter(app => {
      // Map selectedTab to boolean condition
      switch (selectedTab) {
        case 0: // همه
          return true;
        case 1: // در حال اجرا
          return app.is_running;
        case 2: // کاربری
          return !app.is_system;
        case 3: // سیستمی
          return app.is_system;
        default:
          return true;
      }
    });

  if (loading) {
    return <Box sx={{ display: 'flex', justifyContent: 'center', mt: 6 }}><CircularProgress /></Box>;
  }

  if (error) {
    return <Alert severity="error" sx={{ mt: 4 }}>{error}</Alert>;
  }

  return (
    <Box sx={{ mt: 4 }}>
      <Box sx={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', mb: 3 }}>
        <Typography variant="h5" gutterBottom>
          مدیریت اپلیکیشن‌ها
        </Typography>
        <Box sx={{ display: 'flex', gap: 2 }}>
          <Button
            variant="outlined"
            startIcon={<InstallIcon />}
            onClick={() => setInstallDialogOpen(true)}
          >
            نصب اپلیکیشن
          </Button>
          <Button
            variant="outlined"
            startIcon={<ScreenshotIcon />}
            onClick={handleScreenshot}
          >
            اسکرین‌شات
          </Button>
          <Button
            variant="outlined"
            startIcon={<TouchIcon />}
            onClick={() => setUiControlDialogOpen(true)}
          >
            کنترل UI
          </Button>
          <Button
            variant="outlined"
            startIcon={<RefreshIcon />}
            onClick={fetchApps}
            disabled={loading}
          >
            بروزرسانی
          </Button>
        </Box>
      </Box>

      <Box sx={{ mb: 3 }}>
        <TextField
          label="جستجو در اپلیکیشن‌ها"
          variant="outlined"
          size="small"
          value={searchTerm}
          onChange={e => setSearchTerm(e.target.value)}
          InputProps={{
            endAdornment: (
              <InputAdornment position="end">
                <SearchIcon />
              </InputAdornment>
            ),
          }}
          sx={{ width: 320 }}
        />
      </Box>

      <Tabs value={selectedTab} onChange={(_, newValue) => setSelectedTab(newValue)} sx={{ mb: 2 }}>
        <Tab label={`همه (${filteredApps.length})`} />
        <Tab label={`در حال اجرا (${filteredApps.filter(app => app.is_running).length})`} />
        <Tab label={`کاربری (${filteredApps.filter(app => !app.is_system).length})`} />
        <Tab label={`سیستمی (${filteredApps.filter(app => app.is_system).length})`} />
      </Tabs>

      <TableContainer component={Paper}>
        <Table>
          <TableHead>
            <TableRow>
              <TableCell>نام اپلیکیشن</TableCell>
              <TableCell>شناسه</TableCell>
              <TableCell>نسخه</TableCell>
              <TableCell>نوع</TableCell>
              <TableCell>وضعیت</TableCell>
              <TableCell>عملیات</TableCell>
            </TableRow>
          </TableHead>
          <TableBody>
            {getTabApps().map((app) => (
              <TableRow key={app.package_name} hover>
                <TableCell>{app.app_name}</TableCell>
                <TableCell sx={{ fontFamily: 'monospace', fontSize: '0.8rem' }}>
                  {app.package_name}
                </TableCell>
                <TableCell>{app.version_name || '-'}</TableCell>
                <TableCell>
                  <Chip 
                    label={app.is_system ? 'سیستمی' : 'کاربری'} 
                    color={app.is_system ? 'warning' : 'primary'} 
                    size="small" 
                  />
                </TableCell>
                <TableCell>
                  <Box sx={{ display: 'flex', gap: 1 }}>
                    <Chip 
                      label={app.is_enabled ? 'فعال' : 'غیرفعال'} 
                      color={app.is_enabled ? 'success' : 'default'} 
                      size="small" 
                    />
                    {app.is_running && (
                      <Chip label="در حال اجرا" color="info" size="small" />
                    )}
                  </Box>
                </TableCell>
                <TableCell>
                  <Box sx={{ display: 'flex', gap: 1 }}>
                    {!app.is_enabled && (
                      <IconButton
                        size="small"
                        color="success"
                        onClick={() => handleAppAction('enable', app.package_name)}
                        title="فعال کردن"
                      >
                        <PlayIcon />
                      </IconButton>
                    )}
                    {app.is_enabled && (
                      <IconButton
                        size="small"
                        color="warning"
                        onClick={() => handleAppAction('disable', app.package_name)}
                        title="غیرفعال کردن"
                      >
                        <StopIcon />
                      </IconButton>
                    )}
                    {app.is_running && (
                      <IconButton
                        size="small"
                        color="error"
                        onClick={() => handleAppAction('close', app.package_name)}
                        title="بستن"
                      >
                        <StopIcon />
                      </IconButton>
                    )}
                    {!app.is_running && app.is_enabled && (
                      <IconButton
                        size="small"
                        color="primary"
                        onClick={() => handleAppAction('open', app.package_name)}
                        title="باز کردن"
                      >
                        <PlayIcon />
                      </IconButton>
                    )}
                    {!app.is_system && (
                      <IconButton
                        size="small"
                        color="error"
                        onClick={() => handleAppAction('uninstall', app.package_name)}
                        title="حذف"
                      >
                        <DeleteIcon />
                      </IconButton>
                    )}
                  </Box>
                </TableCell>
              </TableRow>
            ))}
          </TableBody>
        </Table>
      </TableContainer>

      {/* Dialog نصب اپلیکیشن */}
      <Dialog open={installDialogOpen} onClose={() => setInstallDialogOpen(false)} maxWidth="sm" fullWidth>
        <DialogTitle>نصب اپلیکیشن جدید</DialogTitle>
        <DialogContent>
          <TextField
            autoFocus
            margin="dense"
            label="مسیر فایل APK"
            fullWidth
            variant="outlined"
            value={apkPath}
            onChange={e => setApkPath(e.target.value)}
            placeholder="/sdcard/Download/app.apk"
          />
        </DialogContent>
        <DialogActions>
          <Button onClick={() => setInstallDialogOpen(false)}>انصراف</Button>
          <Button onClick={handleInstallApp} variant="contained">نصب</Button>
        </DialogActions>
      </Dialog>

      {/* Dialog کنترل UI */}
      <Dialog open={uiControlDialogOpen} onClose={() => setUiControlDialogOpen(false)} maxWidth="sm" fullWidth>
        <DialogTitle>کنترل UI دستگاه</DialogTitle>
        <DialogContent>
          <Grid container spacing={2} sx={{ mt: 1 }}>
            <Grid item xs={6}>
              <TextField
                label="مختصات X"
                type="number"
                fullWidth
                value={uiControlData.x || ''}
                onChange={e => setUiControlData({ ...uiControlData, x: parseInt(e.target.value) || 0 })}
              />
            </Grid>
            <Grid item xs={6}>
              <TextField
                label="مختصات Y"
                type="number"
                fullWidth
                value={uiControlData.y || ''}
                onChange={e => setUiControlData({ ...uiControlData, y: parseInt(e.target.value) || 0 })}
              />
            </Grid>
            <Grid item xs={12}>
              <TextField
                label="متن برای تایپ"
                fullWidth
                value={uiControlData.text || ''}
                onChange={e => setUiControlData({ ...uiControlData, text: e.target.value })}
              />
            </Grid>
            <Grid item xs={12}>
              <Typography variant="subtitle2" gutterBottom>جهت اسکرول:</Typography>
              <Box sx={{ display: 'flex', gap: 1 }}>
                {['up', 'down', 'left', 'right'].map((direction) => (
                  <Button
                    key={direction}
                    variant={uiControlData.direction === direction ? 'contained' : 'outlined'}
                    size="small"
                    onClick={() => setUiControlData({ ...uiControlData, direction: direction as any })}
                  >
                    {direction}
                  </Button>
                ))}
              </Box>
            </Grid>
          </Grid>
        </DialogContent>
        <DialogActions>
          <Button onClick={() => setUiControlDialogOpen(false)}>انصراف</Button>
          <Button onClick={handleUIControl} variant="contained">اجرا</Button>
        </DialogActions>
      </Dialog>

      {/* Dialog اسکرین‌شات */}
      <Dialog open={screenshotDialogOpen} onClose={() => setScreenshotDialogOpen(false)} maxWidth="md" fullWidth>
        <DialogTitle>اسکرین‌شات دستگاه</DialogTitle>
        <DialogContent>
          {screenshotData && (
            <img 
              src={screenshotData} 
              alt="Screenshot" 
              style={{ width: '100%', height: 'auto' }} 
            />
          )}
        </DialogContent>
        <DialogActions>
          <Button onClick={() => setScreenshotDialogOpen(false)}>بستن</Button>
        </DialogActions>
      </Dialog>

      <Snackbar open={snackbarOpen} autoHideDuration={4000} onClose={handleSnackbarClose} anchorOrigin={{ vertical: 'top', horizontal: 'center' }}>
        <MuiAlert onClose={handleSnackbarClose} severity={snackbarSeverity} sx={{ width: '100%' }} elevation={6} variant="filled">
          {snackbarMsg}
        </MuiAlert>
      </Snackbar>
    </Box>
  );
};

export default AppManagement;

import React from 'react';

import {
  Box,
  Grid,
  Card,
  CardContent,
  Typography,
  CircularProgress,
  Chip,
  IconButton,
  Tooltip,
  Container,
} from '@mui/material';
import {
  Devices,
  Wifi,
  WifiOff,
  BatteryChargingFull,
  BatteryFull,
  TrendingUp,
  Error,
  Refresh,
  Security,
  Speed,
} from '@mui/icons-material';
import { useQuery } from 'react-query';
import { formatDistanceToNow } from 'date-fns';
import { faIR } from 'date-fns/locale';
import { analyticsAPI, devicesAPI } from '../services/api';
import CommandResults from '../components/CommandResults';
import { connect as wsConnect, on as wsOn, off as wsOff, isConnected as wsIsConnected, getLastHeartbeat } from '../services/websocket';


const Dashboard: React.FC = () => {
  const [wsConnected, setWsConnected] = React.useState<boolean>(false);
  const [lastHeartbeat, setLastHeartbeat] = React.useState<string | null>(null);

  // Fetch real-time metrics
  const { data: realTimeData, isLoading: realTimeLoading, refetch: refetchRealTime } = useQuery(
    'realTimeMetrics',
    () => analyticsAPI.getRealTimeMetrics(),
    { refetchInterval: 30000 } // Refresh every 30 seconds
  );

  // Fetch device stats
  const { data: deviceStats, isLoading: deviceStatsLoading } = useQuery(
    'deviceStats',
    () => devicesAPI.getDeviceStats()
  );

  // Fetch overview analytics
  const { data: overviewData, isLoading: overviewLoading } = useQuery(
    'overview',
    () => analyticsAPI.getOverview(7) // Last 7 days
  );

  // WebSocket lifecycle and event hooks
  React.useEffect(() => {
    const token = sessionStorage.getItem('access_token') || localStorage.getItem('access_token') || undefined;
    wsConnect(token || undefined);

    const handleConnected = () => setWsConnected(true);
    const handleDisconnected = () => setWsConnected(false);
    const handleAuthenticated = () => {
      setWsConnected(true);
      refetchRealTime();
    };
    const handleHeartbeat = () => {
      setLastHeartbeat(getLastHeartbeat());
      refetchRealTime();
    };
    const handleDataOrCmd = () => {
      refetchRealTime();
    };

    wsOn('ws_connected', handleConnected);
    wsOn('ws_disconnected', handleDisconnected);
    wsOn('authenticated', handleAuthenticated);
    wsOn('heartbeat_ack', handleHeartbeat);
    wsOn('data_received', handleDataOrCmd);
    wsOn('command_result', handleDataOrCmd);

    // initialize local state
    setWsConnected(wsIsConnected());
    setLastHeartbeat(getLastHeartbeat());

    return () => {
      wsOff('ws_connected', handleConnected);
      wsOff('ws_disconnected', handleDisconnected);
      wsOff('authenticated', handleAuthenticated);
      wsOff('heartbeat_ack', handleHeartbeat);
      wsOff('data_received', handleDataOrCmd);
      wsOff('command_result', handleDataOrCmd);
    };
  }, [refetchRealTime]);

  const handleRefresh = () => {
    refetchRealTime();
  };

  // Phase 1: simple test command sender (optional utility)
  const sendTestCommand = async () => {
    try {
      const devicesRes = await devicesAPI.getDevices({ per_page: 50 });
      const list = devicesRes?.data?.devices || devicesRes?.devices || [];
      const target = list.find((d: any) => d.device_id === 'test-device-001');
      if (!target) return;
      await devicesAPI.createCommand(target.id, {
        command_type: 'ping',
        command_data: { message: 'hello' },
        priority: 'normal',
      });
    } catch (e) {
      // swallow for now in Phase 1
    }
  };

  const StatCard: React.FC<{
    title: string;
    value: string | number;
    icon: React.ReactNode;
    color: string;
    subtitle?: string;
    loading?: boolean;
  }> = ({ title, value, icon, color, subtitle, loading }) => (
    <Card className="card-hover" sx={{ height: '100%' }}>
      <CardContent>
        <Box display="flex" alignItems="center" justifyContent="space-between">
          <Box>
            <Typography color="text.secondary" gutterBottom variant="body2">
              {title}
            </Typography>
            <Typography variant="h4" component="div" sx={{ fontWeight: 'bold', color }}>
              {loading ? <CircularProgress size={24} /> : value}
            </Typography>
            {subtitle && (
              <Typography variant="body2" color="text.secondary" sx={{ mt: 1 }}>
                {subtitle}
              </Typography>
            )}
          </Box>
          <Box
            sx={{
              backgroundColor: `${color}20`,
              borderRadius: '50%',
              p: 1,
              display: 'flex',
              alignItems: 'center',
              justifyContent: 'center',
            }}
          >
            {icon}
          </Box>
        </Box>
      </CardContent>
    </Card>
  );

  const DeviceStatusCard: React.FC = () => {
    const onlineCount = realTimeData?.real_time?.online_devices || 0;
    const totalCount = deviceStats?.stats?.total_devices || 0;
    const offlineCount = totalCount - onlineCount;

    return (
      <Card className="card-hover">
        <CardContent>
          <Typography variant="h6" gutterBottom>
            وضعیت دستگاه‌ها
          </Typography>
          <Box display="flex" gap={2} flexWrap="wrap">
            <Chip
              icon={<Wifi />}
              label={`${onlineCount} آنلاین`}
              color="success"
              variant="outlined"
            />
            <Chip
              icon={<WifiOff />}
              label={`${offlineCount} آفلاین`}
              color="error"
              variant="outlined"
            />
            <Chip
              icon={<Devices />}
              label={`${totalCount} کل`}
              color="primary"
              variant="outlined"
            />
          </Box>
        </CardContent>
      </Card>
    );
  };

  const RecentActivityCard: React.FC = () => {
    const recentCommands = realTimeData?.real_time?.recent_commands || 0;
    const recentData = realTimeData?.real_time?.recent_data_collections || 0;
    const recentErrors = realTimeData?.real_time?.recent_errors || 0;

    return (
      <Card className="card-hover">
        <CardContent>
          <Typography variant="h6" gutterBottom>
            فعالیت اخیر (ساعت گذشته)
          </Typography>
          <Box display="flex" flexDirection="column" gap={1}>
            <Box display="flex" justifyContent="space-between" alignItems="center">
              <Typography variant="body2">دستورات اجرا شده:</Typography>
              <Chip label={recentCommands} size="small" color="primary" />
            </Box>
            <Box display="flex" justifyContent="space-between" alignItems="center">
              <Typography variant="body2">جمع‌آوری داده:</Typography>
              <Chip label={recentData} size="small" color="success" />
            </Box>
            <Box display="flex" justifyContent="space-between" alignItems="center">
              <Typography variant="body2">خطاها:</Typography>
              <Chip label={recentErrors} size="small" color="error" />
            </Box>
          </Box>
        </CardContent>
      </Card>
    );
  };

  const PerformanceCard: React.FC = () => {
    const successRate = realTimeData?.real_time?.success_rate_last_hour || 0;

    return (
      <Card className="card-hover">
        <CardContent>
          <Typography variant="h6" gutterBottom>
            نرخ موفقیت
          </Typography>
          <Box display="flex" alignItems="center" gap={2}>
            <CircularProgress
              variant="determinate"
              value={successRate}
              size={60}
              sx={{ color: successRate > 80 ? 'success.main' : successRate > 60 ? 'warning.main' : 'error.main' }}
            />
            <Box>
              <Typography variant="h4" component="div" sx={{ fontWeight: 'bold' }}>
                {successRate.toFixed(1)}%
              </Typography>
              <Typography variant="body2" color="text.secondary">
                دستورات موفق
              </Typography>
            </Box>
          </Box>
        </CardContent>
      </Card>
    );
  };

  return (
    <Container maxWidth="xl">
      {/* Header */}
      <Box display="flex" justifyContent="space-between" alignItems="center" mb={3}>
        <Typography variant="h4" component="h1" sx={{ fontWeight: 'bold' }}>
          داشبورد SystemUpdate
        </Typography>
        <Box display="flex" alignItems="center" gap={1}>
          <Chip
            size="small"
            color={wsConnected ? 'success' : 'default'}
            label={wsConnected ? 'WS Connected' : 'WS Disconnected'}
          />
          {lastHeartbeat && (
            <Chip size="small" color="primary" label={`HB: ${new Date(lastHeartbeat).toLocaleTimeString()}`} />
          )}
          <Tooltip title="بروزرسانی">
            <IconButton onClick={handleRefresh} disabled={realTimeLoading}>
              <Refresh />
            </IconButton>
          </Tooltip>
        </Box>
      </Box>

      {/* Stats Grid */}
      <Grid container spacing={3} mb={3}>
        <Grid item xs={12} sm={6} md={3}>
          <StatCard
            title="دستگاه‌های آنلاین"
            value={realTimeData?.real_time?.online_devices || 0}
            icon={<Wifi />}
            color="#4caf50"
            loading={realTimeLoading}
          />
        </Grid>
        <Grid item xs={12} sm={6} md={3}>
          <StatCard
            title="دستورات اخیر"
            value={realTimeData?.real_time?.recent_commands || 0}
            icon={<TrendingUp />}
            color="#2196f3"
            subtitle="ساعت گذشته"
            loading={realTimeLoading}
          />
        </Grid>
        <Grid item xs={12} sm={6} md={3}>
          <StatCard
            title="جمع‌آوری داده"
            value={realTimeData?.real_time?.recent_data_collections || 0}
            icon={<BatteryFull />}
            color="#ff9800"
            subtitle="ساعت گذشته"
            loading={realTimeLoading}
          />
        </Grid>
        <Grid item xs={12} sm={6} md={3}>
          <StatCard
            title="خطاها"
            value={realTimeData?.real_time?.recent_errors || 0}
            icon={<Error />}
            color="#f44336"
            subtitle="ساعت گذشته"
            loading={realTimeLoading}
          />
        </Grid>
      </Grid>

      {/* Additional Cards */}
      <Grid container spacing={3}>
        <Grid item xs={12} md={4}>
          <DeviceStatusCard />
        </Grid>
        <Grid item xs={12} md={4}>
          <RecentActivityCard />
        </Grid>
        <Grid item xs={12} md={4}>
          <PerformanceCard />
        </Grid>
        <Grid item xs={12}>
          <CommandResults />
        </Grid>
      </Grid>

      {/* Phase 1 utility: trigger a test command roundtrip */}
      <Box mt={2} display="flex" justifyContent="flex-end">
        <Tooltip title="ارسال فرمان آزمایشی به test-device-001">
          <IconButton onClick={sendTestCommand}>
            <Speed />
          </IconButton>
        </Tooltip>
      </Box>

      {/* Last Updated */}
      <Box mt={3} textAlign="center">
        <Typography variant="body2" color="text.secondary">
          آخرین بروزرسانی: {realTimeData?.timestamp ? 
            formatDistanceToNow(new Date(realTimeData.timestamp), {
              addSuffix: true,
              locale: faIR,
            }) : 'نامشخص'}
        </Typography>
      </Box>
    </Container>
  );
};

export default Dashboard;

