import { useAuth } from '../hooks/useAuth';
import CommandPanel from '../components/CommandPanel';

const API_URL = import.meta.env.VITE_API_URL || 'http://localhost:5000/api';

const DeviceDetails: React.FC = () => {
  const { deviceId } = useParams();
  const { token } = useAuth();
  const [device, setDevice] = useState<any>(null);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState('');
  const [snackbarOpen, setSnackbarOpen] = useState(false);
  const [snackbarMsg, setSnackbarMsg] = useState('');
  const [snackbarSeverity, setSnackbarSeverity] = useState<AlertColor>('success');
  const navigate = useNavigate();
  const [deleteDialogOpen, setDeleteDialogOpen] = useState(false);
  const [logs, setLogs] = useState<any[]>([]);
  const [logsLoading, setLogsLoading] = useState(true);
  const [logsError, setLogsError] = useState('');
  const [commandResults, setCommandResults] = useState<any>(null);

  const fetchDevice = useCallback(async () => {
    setLoading(true);
    setError('');
    try {
      if (!token) throw new Error('No access token');
      const res = await axios.get(`${API_URL}/devices/${deviceId}`, {
        headers: { Authorization: `Bearer ${token}` },
      });
      setDevice(res.data.device);
      setSnackbarMsg('اطلاعات دستگاه با موفقیت بارگذاری شد.');
      setSnackbarSeverity('success');
      setSnackbarOpen(true);
    } catch (err: any) {
      setError(err.response?.data?.error || err.message || 'خطا در دریافت اطلاعات دستگاه');
      setSnackbarMsg('خطا در دریافت اطلاعات دستگاه.');
      setSnackbarSeverity('error');
      setSnackbarOpen(true);
    } finally {
      setLoading(false);
    }
  }, [deviceId, token]);

  const fetchLogs = useCallback(async () => {
    setLogsLoading(true);
    setLogsError('');
    try {
      if (!token) throw new Error('No access token');
      const res = await axios.get(`${API_URL}/devices/${deviceId}/logs`, {
        headers: { Authorization: `Bearer ${token}` },
      });
      setLogs(res.data.logs || []);
    } catch (err: any) {
      setLogsError(err.response?.data?.error || err.message || 'خطا در دریافت لاگ‌ها');
    } finally {
      setLogsLoading(false);
    }
  }, [deviceId, token]);

  useEffect(() => {
    fetchDevice();
    fetchLogs();
  }, [fetchDevice, fetchLogs]);

  const handleSnackbarClose = (_event?: React.SyntheticEvent | Event, reason?: string) => {
    if (reason === 'clickaway') return;
    setSnackbarOpen(false);
  };

  const handleRemoteCommand = () => {
    if (device) navigate(`/remote/${device.id}`);
  };
  const handleDeleteClick = () => {
    setDeleteDialogOpen(true);
  };
  const handleDeleteConfirm = async () => {
    try {
      if (!token) throw new Error('No access token');
      await (await import('../services/deviceService')).deleteDevice(token, device.id);
      setSnackbarMsg('دستگاه با موفقیت حذف شد.');
      setSnackbarSeverity('success');
      setSnackbarOpen(true);
      setDeleteDialogOpen(false);
      setTimeout(() => navigate('/devices'), 1200);
    } catch (err: any) {
      setSnackbarMsg('خطا در حذف دستگاه.');
      setSnackbarSeverity('error');
      setSnackbarOpen(true);
      setDeleteDialogOpen(false);
    }
  };
  const handleDeleteCancel = () => {
    setDeleteDialogOpen(false);
  };
  const handleRefresh = () => {
    setLoading(true);
    setError('');
    setSnackbarMsg('در حال بارگذاری مجدد اطلاعات...');
    setSnackbarSeverity('info');
    setSnackbarOpen(true);
    // اجرای دوباره دریافت اطلاعات
    fetchDevice();
  };

  const getEventIcon = (type: string) => {
    switch (type) {
      case 'info':
        return <InfoIcon color="info" fontSize="small" />;
      case 'warning':
        return <WarningIcon color="warning" fontSize="small" />;
      case 'error':
        return <ErrorIcon color="error" fontSize="small" />;
      case 'success':
        return <CheckCircleIcon color="success" fontSize="small" />;
      default:
        return <InfoIcon color="disabled" fontSize="small" />;
    }
  };
  const getStatusChip = (status: string) => {
    switch (status) {
      case 'success':
        return <Chip label="موفق" color="success" size="small" />;
      case 'error':
        return <Chip label="خطا" color="error" size="small" />;
      case 'warning':
        return <Chip label="هشدار" color="warning" size="small" />;
      case 'info':
        return <Chip label="اطلاع" color="info" size="small" />;
      default:
        return <Chip label={status || '-'} size="small" />;
    }
  };

  if (loading) {
    return <Box sx={{ display: 'flex', justifyContent: 'center', mt: 6 }}><CircularProgress /></Box>;
  }
  if (error) {
    return <>
      <Typography color="error" sx={{ mt: 4 }}>{error}</Typography>
      <Snackbar open={snackbarOpen} autoHideDuration={4000} onClose={handleSnackbarClose} anchorOrigin={{ vertical: 'top', horizontal: 'center' }}>
        <MuiAlert onClose={handleSnackbarClose} severity={snackbarSeverity} sx={{ width: '100%' }} elevation={6} variant="filled">
          {snackbarMsg}
        </MuiAlert>
      </Snackbar>
    </>;
  }
  if (!device) {
    return null;
  }

  return (
    <Box sx={{ mt: 4, maxWidth: 600, mx: 'auto' }}>
      <Paper sx={{ p: 3 }}>
        <Box sx={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', mb: 2 }}>
          <Typography variant="h6" gutterBottom>
            اطلاعات دستگاه
          </Typography>
          <Box>
            <Button variant="outlined" color="primary" startIcon={<TerminalIcon />} sx={{ ml: 1 }} onClick={handleRemoteCommand}>
              ارسال دستور
            </Button>
            <Button variant="outlined" color="error" startIcon={<DeleteIcon />} sx={{ ml: 1 }} onClick={handleDeleteClick}>
              حذف
            </Button>
            <Button variant="outlined" color="info" startIcon={<RefreshIcon />} onClick={handleRefresh}>
              رفرش
            </Button>
          </Box>
        </Box>
        <Divider sx={{ mb: 2 }} />
        <Typography><b>شناسه:</b> {device.device_id}</Typography>
        <Typography><b>نام دستگاه:</b> {device.device_name || '-'}</Typography>
        <Typography><b>سازنده:</b> {device.manufacturer || '-'}</Typography>
        <Typography><b>مدل:</b> {device.model || '-'}</Typography>
        <Typography><b>نسخه اندروید:</b> {device.android_version || '-'}</Typography>
        <Typography><b>وضعیت اتصال:</b> {device.is_connected ? <Chip label="متصل" color="success" size="small" /> : <Chip label="قطع" size="small" />}</Typography>
        <Typography><b>آخرین مشاهده:</b> {device.last_seen ? new Date(device.last_seen).toLocaleString('fa-IR') : '-'}</Typography>
        <Typography><b>سطح امنیت:</b> {device.security_level || '-'}</Typography>
        <Typography><b>Root:</b> {device.is_rooted ? 'بله' : 'خیر'}</Typography>
        <Typography><b>Biometric:</b> {device.has_biometric ? 'دارد' : 'ندارد'}</Typography>
        <Typography><b>Battery:</b> {device.battery_level !== undefined ? `${device.battery_level  }%` : '-'}</Typography>
        <Button variant="outlined" sx={{ mt: 3 }} onClick={() => navigate(-1)}>
          بازگشت
        </Button>
      </Paper>
      <Paper sx={{ p: 3, mt: 3 }}>
        <Typography variant="h6" gutterBottom>
          دستورات سریع
        </Typography>
        <Divider sx={{ mb: 2 }} />
        <CommandPanel
          deviceId={parseInt(deviceId!)}
          onSent={(result) => {
            setSnackbarMsg('دستور با موفقیت ارسال شد');
            setSnackbarSeverity('success');
            setSnackbarOpen(true);
            setCommandResults(result);
            fetchLogs();
          }}
        />
        {commandResults && (
          <Alert severity="info" sx={{ mt: 2 }}>
            نتیجه: {JSON.stringify(commandResults)}
          </Alert>
        )}
      </Paper>
      <Divider sx={{ my: 4 }} />
      <Typography variant="h6" gutterBottom>
        لاگ‌ها و تاریخچه فعالیت
      </Typography>
      {logsLoading ? (
        <Box sx={{ display: 'flex', justifyContent: 'center', my: 3 }}><CircularProgress /></Box>
      ) : logsError ? (
        <Alert severity="error">{logsError}</Alert>
      ) : logs.length === 0 ? (
        <Alert severity="info">لاگی برای این دستگاه ثبت نشده است.</Alert>
      ) : (
        <TableContainer component={Paper} sx={{ mb: 2, maxWidth: '100vw', overflowX: 'auto' }}>
          <Table size="small">
            <TableHead>
              <TableRow>
                <TableCell>زمان</TableCell>
                <TableCell>نوع رویداد</TableCell>
                <TableCell>توضیحات</TableCell>
                <TableCell>وضعیت</TableCell>
              </TableRow>
            </TableHead>
            <TableBody>
              {logs.map((log, idx) => (
                <TableRow key={idx}>
                  <TableCell>{log.timestamp ? new Date(log.timestamp).toLocaleString('fa-IR') : '-'}</TableCell>
                  <TableCell>
                    <Box sx={{ display: 'flex', alignItems: 'center', gap: 1 }}>
                      {getEventIcon(log.event_type)}
                      <span>{log.event_type || '-'}</span>
                    </Box>
                  </TableCell>
                  <TableCell>
                    <Tooltip title={log.message || '-'}>
                      <span style={{ whiteSpace: 'nowrap', overflow: 'hidden', textOverflow: 'ellipsis', display: 'inline-block', maxWidth: 180 }}>
                        {log.message || '-'}
                      </span>
                    </Tooltip>
                  </TableCell>
                  <TableCell>{getStatusChip(log.status)}</TableCell>
                </TableRow>
              ))}
            </TableBody>
          </Table>
        </TableContainer>
      )}
      <Dialog open={deleteDialogOpen} onClose={handleDeleteCancel}>
        <DialogTitle>تایید حذف دستگاه</DialogTitle>
        <DialogContent>
          <DialogContentText>
            آیا از حذف دستگاه "{device?.device_name || device?.device_id}" مطمئن هستید؟ این عملیات غیرقابل بازگشت است.
          </DialogContentText>
        </DialogContent>
        <DialogActions>
          <Button onClick={handleDeleteCancel}>انصراف</Button>
          <Button onClick={handleDeleteConfirm} color="error" variant="contained">حذف</Button>
        </DialogActions>
      </Dialog>
      <Snackbar open={snackbarOpen} autoHideDuration={4000} onClose={handleSnackbarClose} anchorOrigin={{ vertical: 'top', horizontal: 'center' }}>
        <MuiAlert onClose={handleSnackbarClose} severity={snackbarSeverity} sx={{ width: '100%' }} elevation={6} variant="filled">
          {snackbarMsg}
        </MuiAlert>
      </Snackbar>
    </Box>
  );
};

export default DeviceDetails;

import React from 'react';
import { render, screen, waitFor, fireEvent } from '@testing-library/react';
import DeviceList from './DeviceList';
import { AuthProvider } from '../contexts/AuthContext';
import * as deviceService from '../services/deviceService';

jest.mock('../services/deviceService');

const mockDevices = [
  {
    id: 1,
    device_id: 'dev-001',
    device_name: 'Test Device',
    manufacturer: 'TestCo',
    model: 'T1000',
    is_connected: true,
    security_level: 'high',
  },
  {
    id: 2,
    device_id: 'dev-002',
    device_name: 'Device 2',
    manufacturer: 'BrandX',
    model: 'X200',
    is_connected: false,
    security_level: 'medium',
  },
];

describe('DeviceList', () => {
  beforeEach(() => {
    jest.clearAllMocks();
  });

  it('renders loading indicator initially', async () => {
    (deviceService.getDevices as jest.Mock).mockImplementation(() => new Promise(() => {}));
    render(
      <AuthProvider>
        <DeviceList />
      </AuthProvider>
    );
    expect(screen.getByRole('progressbar')).toBeInTheDocument();
  });

  it('renders devices after loading', async () => {
    (deviceService.getDevices as jest.Mock).mockResolvedValue({ devices: mockDevices, pagination: { page: 1, per_page: 10, total: 2, pages: 1, has_next: false, has_prev: false } });
    render(
      <AuthProvider>
        <DeviceList />
      </AuthProvider>
    );
    await waitFor(() => expect(screen.getByText('Test Device')).toBeInTheDocument());
    expect(screen.getByText('Device 2')).toBeInTheDocument();
  });

  it('shows error message on fetch failure', async () => {
    (deviceService.getDevices as jest.Mock).mockRejectedValue(new Error('Fetch error'));
    render(
      <AuthProvider>
        <DeviceList />
      </AuthProvider>
    );
    await waitFor(() => expect(screen.getByText(/خطا در دریافت دستگاه‌ها/)).toBeInTheDocument());
  });

  it('filters devices by search', async () => {
    (deviceService.getDevices as jest.Mock).mockResolvedValue({ devices: mockDevices, pagination: { page: 1, per_page: 10, total: 2, pages: 1, has_next: false, has_prev: false } });
    render(
      <AuthProvider>
        <DeviceList />
      </AuthProvider>
    );
    await waitFor(() => expect(screen.getByText('Test Device')).toBeInTheDocument());
    const searchInput = screen.getByPlaceholderText(/جستجو/i);
    fireEvent.change(searchInput, { target: { value: 'Device 2' } });
    fireEvent.submit(searchInput);
    await waitFor(() => expect(screen.getByText('Device 2')).toBeInTheDocument());
  });
});

import React, { useEffect, useRef, useState } from 'react';

import { Table, TableBody, TableCell, TableContainer, TableHead, TableRow, Paper, Typography, CircularProgress, Box, Chip, Pagination, TextField, InputAdornment, IconButton, Button, MenuItem, Select, FormControl, InputLabel, TableSortLabel } from '@mui/material';
import SearchIcon from '@mui/icons-material/Search';
import RefreshIcon from '@mui/icons-material/Refresh';
import { useNavigate } from 'react-router-dom';
import Snackbar from '@mui/material/Snackbar';
import MuiAlert, { AlertColor } from '@mui/material/Alert';
import DeleteIcon from '@mui/icons-material/Delete';
import InfoIcon from '@mui/icons-material/Info';
import TerminalIcon from '@mui/icons-material/Terminal';
import Tooltip from '@mui/material/Tooltip';
import Dialog from '@mui/material/Dialog';
import DialogTitle from '@mui/material/DialogTitle';
import DialogContent from '@mui/material/DialogContent';
import DialogContentText from '@mui/material/DialogContentText';
import DialogActions from '@mui/material/DialogActions';
import BatteryChargingFullIcon from '@mui/icons-material/BatteryChargingFull';
import BatteryFullIcon from '@mui/icons-material/BatteryFull';
import CircleIcon from '@mui/icons-material/Circle';
import RadioButtonUncheckedIcon from '@mui/icons-material/RadioButtonUnchecked';
import { useAuth } from '../hooks/useAuth';
import { getDevices, Device } from '../services/deviceService';
import { on as wsOn, off as wsOff } from '../services/websocket';

const DeviceList: React.FC = () => {
  const { token } = useAuth();
  const [devices, setDevices] = useState<Device[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState('');
  const [page, setPage] = useState(1);
  const [totalPages, setTotalPages] = useState(1);
  const [search, setSearch] = useState('');
  const [searchInput, setSearchInput] = useState('');
  const [snackbarOpen, setSnackbarOpen] = useState(false);
  const [snackbarMsg, setSnackbarMsg] = useState('');
  const [snackbarSeverity, setSnackbarSeverity] = useState<AlertColor>('success');
  const navigate = useNavigate();
  const [connectionFilter, setConnectionFilter] = useState('all');
  const [securityFilter, setSecurityFilter] = useState('all');
  const [orderBy, setOrderBy] = useState<keyof Device>('device_id');
  const [order, setOrder] = useState<'asc' | 'desc'>('asc');
  const [deleteDialogOpen, setDeleteDialogOpen] = useState(false);
  const [deviceToDelete, setDeviceToDelete] = useState<Device | null>(null);

  const fetchDevices = async (showSuccess = true) => {
    setLoading(true);
    setError('');
    try {
      if (!token) throw new Error('No access token');
      const res = await getDevices(token, page, 10);
      let filtered = res.devices;
      if (search) {
        const s = search.trim().toLowerCase();
        filtered = filtered.filter(
          d =>
            d.device_id?.toLowerCase().includes(s) ||
            d.device_name?.toLowerCase().includes(s) ||
            d.manufacturer?.toLowerCase().includes(s) ||
            d.model?.toLowerCase().includes(s)
        );
      }
      if (connectionFilter !== 'all') {
        filtered = filtered.filter((d) => {
          if (connectionFilter === 'connected') {
            return d.is_connected;
          } if (connectionFilter === 'disconnected') {
            return !d.is_connected;
          }
          return true;
        });
      }
      if (securityFilter !== 'all') {
        filtered = filtered.filter((d) => d.security_level === securityFilter);
      }
      setDevices(filtered);
      setTotalPages(res.pagination.pages);
      if (showSuccess) {
        setSnackbarMsg('دستگاه‌ها با موفقیت بارگذاری شدند.');
        setSnackbarSeverity('success');
        setSnackbarOpen(true);
      }
    } catch (err: any) {
      setError(err.response?.data?.error || err.message || 'خطا در دریافت دستگاه‌ها');
      setSnackbarMsg('خطا در دریافت دستگاه‌ها.');
      setSnackbarSeverity('error');
      setSnackbarOpen(true);
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    fetchDevices(false);
  }, [token, page, search, connectionFilter, securityFilter]);

  // Debounced refetch to avoid bursts on multiple WS events
  const refetchTimer = useRef<number | null>(null);
  const debouncedRefresh = () => {
    if (refetchTimer.current) window.clearTimeout(refetchTimer.current);
    refetchTimer.current = window.setTimeout(() => fetchDevices(false), 400);
  };

  // Helpers to update device list in place
  const updateDeviceStatus = (device_id: string, is_connected: boolean, last_seen?: string) => {
    setDevices(prev => prev.map(d => d.device_id === device_id ? { ...d, is_connected, last_seen: last_seen ?? d.last_seen } : d));
  };
  const updateDeviceInList = (partial: Partial<Device> & { device_id?: string }) => {
    if (!partial.device_id) return;
    setDevices(prev => prev.map(d => d.device_id === partial.device_id ? { ...d, ...partial } as Device : d));
  };

  // WebSocket subscriptions for real-time updates
  useEffect(() => {
    const onAuthenticated = (data: any) => {
      // A device connected successfully
      if (data?.device?.device_id) {
        updateDeviceStatus(data.device.device_id, true, new Date().toISOString());
        debouncedRefresh();
      }
    };
    const onDeviceUpdate = (payload: any) => {
      // payload may contain fields like device_id, battery_level, last_seen, is_connected
      if (payload?.device_id) {
        updateDeviceInList(payload);
      }
    };
    const onDeviceOffline = (deviceId: string | { device_id?: string }) => {
      const id = typeof deviceId === 'string' ? deviceId : deviceId?.device_id;
      if (id) updateDeviceStatus(id, false, new Date().toISOString());
    };
    const onCommandResult = () => {
      debouncedRefresh();
    };

    wsOn('authenticated', onAuthenticated);
    wsOn('device_update', onDeviceUpdate);
    wsOn('device_offline', onDeviceOffline);
    wsOn('command_result', onCommandResult);

    return () => {
      wsOff('authenticated', onAuthenticated);
      wsOff('device_update', onDeviceUpdate);
      wsOff('device_offline', onDeviceOffline);
      wsOff('command_result', onCommandResult);
    };
  }, []);

  const handleSearch = (e: React.FormEvent) => {
    e.preventDefault();
    setPage(1);
    setSearch(searchInput);
    setSnackbarMsg('جستجو انجام شد.');
    setSnackbarSeverity('info');
    setSnackbarOpen(true);
  };

  const handleRefresh = () => {
    fetchDevices();
    setSnackbarMsg('در حال بارگذاری مجدد...');
    setSnackbarSeverity('info');
    setSnackbarOpen(true);
  };

  const handleSnackbarClose = (_event?: React.SyntheticEvent | Event, reason?: string) => {
    if (reason === 'clickaway') return;
    setSnackbarOpen(false);
  };

  const handleRowClick = (device: Device) => {
    navigate(`/devices/${device.id}`);
  };

  const handleDeleteClick = (device: Device) => {
    setDeviceToDelete(device);
    setDeleteDialogOpen(true);
  };

  const handleDeleteConfirm = async () => {
    if (!deviceToDelete) return;
    try {
      if (!token) throw new Error('No access token');
      await (await import('../services/deviceService')).deleteDevice(token, deviceToDelete.id);
      setSnackbarMsg('دستگاه با موفقیت حذف شد.');
      setSnackbarSeverity('success');
      setSnackbarOpen(true);
      setDeleteDialogOpen(false);
      setDeviceToDelete(null);
      fetchDevices(false);
    } catch (err: any) {
      setSnackbarMsg('خطا در حذف دستگاه.');
      setSnackbarSeverity('error');
      setSnackbarOpen(true);
      setDeleteDialogOpen(false);
      setDeviceToDelete(null);
    }
  };

  const handleDeleteCancel = () => {
    setDeleteDialogOpen(false);
    setDeviceToDelete(null);
  };

  const handleRemoteCommand = (device: Device) => {
    navigate(`/remote/${device.id}`);
  };

  const handleDetails = (device: Device) => {
    navigate(`/devices/${device.id}`);
  };

  const filteredDevices = devices.filter((d) => {
    let match = true;
    if (connectionFilter !== 'all') {
      match = match && ((connectionFilter === 'connected' && d.is_connected) || (connectionFilter === 'disconnected' && !d.is_connected));
    }
    if (securityFilter !== 'all') {
      match = match && d.security_level === securityFilter;
    }
    return match;
  });

  const handleSort = (property: keyof Device) => {
    const isAsc = orderBy === property && order === 'asc';
    setOrder(isAsc ? 'desc' : 'asc');
    setOrderBy(property);
  };

  function sortDevices(array: Device[], comparator: (a: Device, b: Device) => number) {
    const stabilized = array.map((el, index) => [el, index] as [Device, number]);
    stabilized.sort((a, b) => {
      const order = comparator(a[0], b[0]);
      if (order !== 0) return order;
      return a[1] - b[1];
    });
    return stabilized.map((el) => el[0]);
  }

  function getComparator<Key extends keyof Device>(order: 'asc' | 'desc', orderBy: Key): (a: Device, b: Device) => number {
    return order === 'desc'
      ? (a, b) => descendingComparator(a, b, orderBy)
      : (a, b) => -descendingComparator(a, b, orderBy);
  }

  function descendingComparator<T>(a: T, b: T, orderBy: keyof T) {
    if (b[orderBy] === undefined || b[orderBy] === null) return -1;
    if (a[orderBy] === undefined || a[orderBy] === null) return 1;
    if (typeof b[orderBy] === 'string' && typeof a[orderBy] === 'string') {
      return b[orderBy].localeCompare(a[orderBy]);
    }
    if (b[orderBy] < a[orderBy]) {
      return -1;
    }
    if (b[orderBy] > a[orderBy]) {
      return 1;
    }
    return 0;
  }

  const sortedDevices = sortDevices(filteredDevices, getComparator(order, orderBy));

  return (
    <Box sx={{ mt: 4 }}>
      <Box sx={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', mb: 2 }}>
        <Typography variant="h5" gutterBottom>
          لیست دستگاه‌ها
        </Typography>
        <Button
          variant="outlined"
          startIcon={<RefreshIcon />}
          onClick={handleRefresh}
          disabled={loading}
        >
          بارگذاری مجدد
        </Button>
      </Box>
      <Box component="form" onSubmit={handleSearch} sx={{ mb: 2, display: 'flex', gap: 2, flexWrap: 'wrap' }}>
        <TextField
          label="جستجو (نام، شناسه، سازنده، مدل)"
